namespace {if(!function_exists('sanitize_key')){function sanitize_key($key):string{return strtolower(preg_replace('/[^a-z0-9_\-]/','',(string)$key));}}if(!function_exists('__')){function __($text,$domain=null):string{return(string)$text;}}if(!function_exists('apply_filters')){function apply_filters($hook,$value){return$value;}}}
namespace ProjectPress\Tests\Unit {use PHPUnit\Framework\TestCase;use ProjectPress\Includes\Core\Editor;final class EditorTest extends TestCase{public function testCreateRegistersDynamicEditorDefinitions():void{$this->assertTrue(Editor::create('projectpress_primary_editor',array('label'=>'Primary Editor','description'=>'Main editor','supports'=>array('title','content'))));$this->assertArrayHasKey('projectpress_primary_editor',Editor::definitions());$this->assertSame('Primary Editor',Editor::definitions()['projectpress_primary_editor']['label']);}public function testDynamicallyCreateNormalizesSlugAndConfig():void{$this->assertTrue(Editor::dynamically_create(array('slug'=>'Primary Editor','label'=>'Primary Editor','supports'=>array('title','content'))));$this->assertArrayHasKey('primary_editor',Editor::definitions());$this->assertSame('',Editor::definitions()['primary_editor']['post_type']);}public function testDynamicallyCreateAcceptsProjectPostType():void{$this->assertTrue(Editor::dynamically_create(array('slug'=>'projects_editor','label'=>'Projects Editor','post_type'=>'projectpress_project','supports'=>array('title','content'))));$this->assertSame('projectpress_project',Editor::definitions()['projects_editor']['post_type']);}}}
